      containerChecksumBuffer.putLong(blockTreeProto.getDataChecksum());
    }
    containerChecksumBuffer.flip();
    checksumImpl.update(containerChecksumBuffer);

    return containerTreeBuilder
        .setDataChecksum(checksumImpl.getValue())
        .build();
  }

